// ── 1. Inputs ──────────────────────────────────────────────────────────────────
// Windowed fetch — time-bounded, both accounts
let allWorkItems = [];
try { allWorkItems.push(...$('HTTP Request - Work').all()); } catch (e) {}
try { allWorkItems.push(...$('HTTP Request - Work SENT').all()); } catch (e) {}

let allPersonalItems = [];
try { allPersonalItems.push(...$('HTTP Request - Personal').all()); } catch (e) {}
try { allPersonalItems.push(...$('HTTP Request - Personal SENT').all()); } catch (e) {}

// Starred fetch — unbounded, both accounts
let allWorkStarredItems = [];
try { allWorkStarredItems.push(...$('HTTP Request - Work Starred').all()); } catch (e) {}

let allPersonalStarredItems = [];
try { allPersonalStarredItems.push(...$('HTTP Request - Personal Starred').all()); } catch (e) {}

// feedsSince: UTC ISO string — read from Config
const feedsSince = $('Config').first().json.feedsSince || null;

// ── 2. User Config ──────────────────────────────────────────────────────────────
const config = {
  workEmail: 'REDACTED-EMAIL',
  personalEmail: 'REDACTED-EMAIL',
  maxBodyLength: 2500
};

// ── 3. Helpers ──────────────────────────────────────────────────────────────────
function decodeBase64(data) {
  if (!data) return "";
  const base64 = data.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(base64, 'base64').toString('utf-8');
}

function decodeHtmlEntities(str) {
  if (!str) return '';
  return str
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&#x27;/g, "'").replace(/&#x2F;/g, '/')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
}

function stripHtmlTags(html) {
  if (!html) return "";
  let text = html
    .replace(/<style[^>]*>[^]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[^]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n')
    .replace(/<div[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ');
  text = decodeHtmlEntities(text);
  text = text.replace(/^[ \t]+|[ \t]+$/gm, '').replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n');
  return text.trim();
}

function chopTextReplies(text) {
  if (!text) return "";
  const patterns = [
    /\nFrom:[\s\S]{1,250}?\nSent:/i, /\nFrom:[\s\S]{1,250}?\nDate:/i,
    /\n[-_]{7,}/, /\n-{7,}\s*Original Message/i, /\nOn[\s\S]{1,250}?\bwrote:/i
  ];
  let cutIndex = text.length;
  for (const pattern of patterns) {
    const match = text.search(pattern);
    if (match !== -1 && match < cutIndex) cutIndex = match;
  }
  return text.substring(0, cutIndex).trim();
}

function getCleanedBody(payload) {
  if (!payload) return "";
  let htmlData = "", textData = "";
  function findParts(p) {
    if (p.mimeType === 'text/html' && p.body?.data) htmlData = decodeBase64(p.body.data);
    else if (p.mimeType === 'text/plain' && p.body?.data) textData = decodeBase64(p.body.data);
    if (p.parts) p.parts.forEach(findParts);
  }
  if (payload.body?.data && payload.mimeType) {
    if (payload.mimeType === 'text/html') htmlData = decodeBase64(payload.body.data);
    if (payload.mimeType === 'text/plain') textData = decodeBase64(payload.body.data);
  }
  findParts(payload);
  let processedText = "";
  if (htmlData) {
    const htmlSplitters = ['<div class="gmail_quote', '<div class="gmail_extra', '<blockquote', '<hr tabindex="-1"', '<div id="appendonsend"', '<div style="border:none;border-top:solid #B5C4DF'];
    let lowerHtml = htmlData.toLowerCase();
    let cutIndex = htmlData.length;
    for (const splitter of htmlSplitters) {
      const idx = lowerHtml.indexOf(splitter.toLowerCase());
      if (idx !== -1 && idx < cutIndex) cutIndex = idx;
    }
    processedText = stripHtmlTags(htmlData.substring(0, cutIndex));
  } else if (textData) {
    processedText = decodeHtmlEntities(textData);
  }
  return chopTextReplies(processedText);
}

function getCategory(labels = []) {
  if (labels.includes('CATEGORY_PROMOTIONS') || labels.includes('CATEGORY_SOCIAL')) return 'noise';
  if (labels.includes('CATEGORY_UPDATES')) return 'updates';
  return 'attention';
}

function isSentEmail(labels = [], fromHeader = '') {
  if (!labels || !Array.isArray(labels)) return false;
  if (!labels.includes('SENT')) return false;
  const fromLower = (fromHeader || '').toLowerCase();
  return fromLower.includes(config.workEmail.toLowerCase()) || fromLower.includes(config.personalEmail.toLowerCase());
}

// ── 4. Build JSON message objects ───────────────────────────────────────────────
// source_type: 'gmail_starred' for starred fetch, 'gmail' for windowed fetch
function buildMessage(item, account, sourceType) {
  const e = item.json;
  if (!e.id || !e.payload) return null;
  const headers = e.payload?.headers || [];
  const findHeader = (name) => headers.find(h => h.name.toLowerCase() === name.toLowerCase())?.value || '';
  const labels  = e.labelIds || [];
  const fromRaw = findHeader('From');
  const isSent  = isSentEmail(labels, fromRaw);
  const toRaw   = findHeader('To');
  const ccRaw   = findHeader('Cc');
  const recipients = [];
  if (toRaw) recipients.push(...toRaw.split(',').map(s => s.trim()).filter(Boolean));
  if (ccRaw) recipients.push(...ccRaw.split(',').map(s => s.trim()).filter(Boolean));
  let body = getCleanedBody(e.payload);
  body = body.replace(/\s+/g, ' ').trim().substring(0, config.maxBodyLength);
  const timestampUTC = e.internalDate
    ? new Date(parseInt(e.internalDate)).toISOString()
    : null;
  return {
    source:         'gmail',
    source_type:    sourceType,
    message_id:     e.id,
    thread_id:      e.threadId || null,
    timestamp:      timestampUTC,
    timezone:       'UTC',
    subject:        decodeHtmlEntities(findHeader('Subject') || '(No Subject)'),
    sender:         fromRaw || '(Unknown Sender)',
    recipients,
    body,
    is_starred:     labels.includes('STARRED'),
    is_unread:      labels.includes('UNREAD'),
    is_sent:        isSent,
    account,
    gmail_category: isSent ? 'sent' : getCategory(labels),
    url:            `https://mail.google.com/mail/u/0/#all/${e.id}`
  };
}

// ── 5. Process all items ─────────────────────────────────────────────────────────
// Build starred set first. Then layer windowed messages on top,
// skipping any already captured as starred (starred version always wins).
const starredById = new Map();

for (const item of allWorkStarredItems) {
  const msg = buildMessage(item, 'work', 'gmail_starred');
  if (msg && !starredById.has(msg.message_id)) starredById.set(msg.message_id, msg);
}
for (const item of allPersonalStarredItems) {
  const msg = buildMessage(item, 'personal', 'gmail_starred');
  if (msg && !starredById.has(msg.message_id)) starredById.set(msg.message_id, msg);
}

const messages = [...starredById.values()];
const seenIds = new Set(starredById.keys());

for (const item of allWorkItems) {
  const msg = buildMessage(item, 'work', 'gmail');
  if (msg && !seenIds.has(msg.message_id)) { seenIds.add(msg.message_id); messages.push(msg); }
}
for (const item of allPersonalItems) {
  const msg = buildMessage(item, 'personal', 'gmail');
  if (msg && !seenIds.has(msg.message_id)) { seenIds.add(msg.message_id); messages.push(msg); }
}

// ── 6. Filter windowed messages by feedsSince; starred messages are exempt ───────
// Starred items always pass through regardless of age.
const filtered = feedsSince
  ? messages.filter(m => m.source_type === 'gmail_starred' || !m.timestamp || m.timestamp >= feedsSince)
  : messages;

// Sort ascending by timestamp
filtered.sort((a, b) => {
  if (!a.timestamp) return 1;
  if (!b.timestamp) return -1;
  return a.timestamp.localeCompare(b.timestamp);
});

// ── 7. Wrap in fenced JSON block for Obsidian .md storage ────────────────────────
const fence = '```';
const content = `${fence}json\n${JSON.stringify(filtered, null, 2)}\n${fence}`;

return [{ json: { content } }];
